  {
   "tipo": "script_godot",
   "codice": "extends "res://htd/htd_test.gd"


func _run_tests() -> void:
	var main := await instantiate_main_scene()
	if not check("main", main != null, "La scena principale deve caricarsi senza errori"):
		return
	var warrior_a := find_by_name(main, "WarriorA")
	var warrior_b := find_by_name(main, "WarriorB")
	if not check("warriors", warrior_a != null and warrior_b != null, "Servono entrambi i nodi WarriorA e WarriorB"):
		return
	call_if_exists(warrior_a, "take_damage", [5])
	await wait_frames(2)
	var hp_a = get_prop(get_prop(warrior_a, "stats"), "health")
	var hp_b = get_prop(get_prop(warrior_b, "stats"), "health")
	check("hp_a_reduced", hp_a == 15, "WarriorA doveva passare da 20 a 15 HP (ha %s HP)" % str(hp_a))
	check("hp_b_intact", hp_b == 20, "WarriorB deve rimanere intatto a 20 HP (ha %s HP)" % str(hp_b))
",
   "descrizione": "Ferire WarriorA non modifica i punti vita di WarriorB"
  }
